// HasRecording applies the HasEdge predicate on the "recording" edge.
func HasRecording() predicate.RecordingVersion {
	return predicate.RecordingVersion(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, RecordingTable, RecordingColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRecordingWith applies the HasEdge predicate on the "recording" edge with a given conditions (other predicates).
func HasRecordingWith(preds ...predicate.Recording) predicate.RecordingVersion {
	return predicate.RecordingVersion(func(s *sql.Selector) {
		step := newRecordingStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RecordingVersion) predicate.RecordingVersion {
	return predicate.RecordingVersion(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RecordingVersion) predicate.RecordingVersion {
	return predicate.RecordingVersion(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RecordingVersion) predicate.RecordingVersion {
	return predicate.RecordingVersion(sql.NotPredicates(p))
}
